fn make_contract(id: u16, name: &str) -> Result<vb_core::action::ActionContract, Box<dyn std::error::Error>> {
    Ok(vb_core::action::ActionContract {
        id: ActionId::new(id),
        name: vb_core::action::ActionName::new(name)?,
        input_slot_count: 1,
        output_slot_count: 1,
        max_input_bytes: 1024,
