    let mut shard = test_shard();
    let workflow = do_workflow(0)?;
    let contract = make_contract(0, "real_action")?;
    let result = shard.validate_submit_admission_with_contracts(
        RunId::new(1), &workflow, CapabilitySet::empty(), &[contract],
